const item = $json ?? {};
const attachments = Array.isArray(item.attachments) ? item.attachments : [];
const body = item.body ?? {};
const bodyAtts = Array.isArray(body.attachments) ? body.attachments : [];
const allAtts = [...attachments, ...bodyAtts];
const rawAtt = allAtts.find(a => String(a.kind || a.file_type || a.fileType || '').toLowerCase() === 'audio') ?? allAtts[0] ?? {};

const candidateUrl = String(rawAtt.dataUrl ?? rawAtt.data_url ?? rawAtt.url ?? '').trim();

if (!candidateUrl) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] Não foi possível obter o link do arquivo de áudio.',
      normalizationStatus: 'failed',
      normalizationPendingStep: 'audio_url_missing'
    }
  };
}

// 1. Download do áudio via fetch com suporte a redirects
let buffer;
try {
  const resp = await fetch(candidateUrl);
  if (!resp.ok) {
    throw new Error(`HTTP ${resp.status}`);
  }
  const ab = await resp.arrayBuffer();
  buffer = Buffer.from(ab);
} catch (err) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] Não foi possível carregar o arquivo de áudio.',
      normalizationStatus: 'failed',
      normalizationPendingStep: 'audio_download_failed'
    }
  };
}

// 2. Validação de tamanho (máximo 10 MiB)
const MAX_ATTACHMENT_BYTES = 10 * 1024 * 1024;
if (buffer.length > MAX_ATTACHMENT_BYTES) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] O áudio enviado excede o limite máximo de 10 MB. Por favor, envie um arquivo menor ou envie sua mensagem por texto.',
      normalizationStatus: 'unsupported',
      normalizationPendingStep: 'attachment_exceeds_10mb_limit'
    }
  };
}

// 3. Validação de duração (máximo 60 segundos)
function parseOggOpus(buf) {
  if (buf.length < 27 || buf.toString('ascii', 0, 4) !== 'OggS') return null;
  let offset = 0, maxGranule = null, preSkip = 0, found = false;
  const unset = 0xffffffffffffffffn;
  while (offset + 27 <= buf.length) {
    if (buf.toString('ascii', offset, offset + 4) !== 'OggS' || buf[offset + 4] !== 0) return null;
    const count = buf[offset + 26], table = offset + 27, payload = table + count;
    if (payload > buf.length) return null;
    let length = 0;
    for (let i = 0; i < count; i++) length += buf[table + i];
    const end = payload + length;
    if (end > buf.length) return null;
    if (!found) {
      const marker = buf.indexOf('OpusHead', payload, 'ascii');
      if (marker >= payload && marker + 12 <= end) { preSkip = buf.readUInt16LE(marker + 10); found = true; }
    }
    const granule = buf.readBigUInt64LE(offset + 6);
    if (granule !== unset && (maxGranule === null || granule > maxGranule)) maxGranule = granule;
    offset = end;
  }
  if (!found || maxGranule === null) return null;
  const samples = Number(maxGranule) - preSkip;
  return Number.isFinite(samples) && samples >= 0 ? samples / 48000 : null;
}

function parseWav(buf) {
  if (buf.length < 44 || buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') return null;
  let offset = 12, byteRate = 0, dataBytes = null;
  while (offset + 8 <= buf.length) {
    const id = buf.toString('ascii', offset, offset + 4), size = buf.readUInt32LE(offset + 4), start = offset + 8;
    const actual = Math.min(size, Math.max(0, buf.length - start));
    if (id === 'fmt ' && actual >= 16) byteRate = buf.readUInt32LE(start + 8);
    if (id === 'data') dataBytes = actual;
    offset = start + size + (size % 2);
    if (id === 'data' && byteRate > 0) break;
  }
  return byteRate > 0 && dataBytes !== null ? dataBytes / byteRate : null;
}

const MAX_AUDIO_SECONDS = 60;
const durationSeconds = parseOggOpus(buffer) ?? parseWav(buffer) ?? (rawAtt.durationSeconds ? Number(rawAtt.durationSeconds) : null);

if (durationSeconds !== null && durationSeconds > MAX_AUDIO_SECONDS) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] O áudio enviado tem duração superior a 60 segundos. Por favor, envie um áudio mais curto ou digite sua mensagem.',
      normalizationStatus: 'unsupported',
      normalizationPendingStep: 'audio_over_60_seconds'
    }
  };
}

// 4. Transcrição via Speaches
let transcriptText = '';
try {
  const blob = new Blob([buffer], { type: rawAtt.mimeType || 'audio/ogg' });
  const form = new FormData();
  form.append('file', blob, rawAtt.fileName || 'audio.oga');
  form.append('model', 'Systran/faster-whisper-small');
  form.append('language', 'pt');
  form.append('prompt', 'Transcrição fiel de uma mensagem de voz em português do Brasil, com palavras e letras soletradas.');

  const sttResp = await fetch('http://speaches:8000/v1/audio/transcriptions', {
    method: 'POST',
    body: form
  });

  if (!sttResp.ok) {
    const errBody = await sttResp.text();
    throw new Error(`Speaches error: ${sttResp.status} - ${errBody}`);
  }

  const sttJson = await sttResp.json();
  transcriptText = String(sttJson.text ?? sttJson.transcription ?? '').trim();
} catch (sttErr) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] O serviço de transcrição não conseguiu processar este áudio. Por favor, tente enviar novamente ou escreva por texto.',
      normalizationStatus: 'failed',
      normalizationPendingStep: 'audio_transcription_failed'
    }
  };
}

if (!transcriptText) {
  return {
    json: {
      ...item,
      contentText: '[Contexto interno dos anexos — não é texto escrito pelo usuário] O áudio enviado não continha fala audível identificável.',
      normalizationStatus: 'failed',
      normalizationPendingStep: 'audio_transcription_empty'
    }
  };
}

// 5. Sucesso na transcrição
return {
  json: {
    ...item,
    contentText: transcriptText,
    normalizationStatus: 'ready',
    normalizationPendingStep: '',
    durationSeconds,
    transcription: transcriptText
  }
};
